css:
[data-bz-node="s6r1"][data-bz-node]{grid-template-columns:repeat(auto-fit, minmax(260px, 1fr))}
[data-bz-node^="s6c2-r"][data-bz-node]{border-style:solid;align-content:start;border-top-color:#c41230;border-right-color:#edebe3;border-bottom-color:#edebe3;border-left-color:#edebe3}
[data-bz-node^="s6h3-r"][data-bz-node] h2{font-family:Oswald, sans-serif;font-size:24px;font-weight:700;font-style:normal;line-height:1.1;letter-spacing:normal;text-transform:uppercase;text-align:start;color:rgb(20, 21, 26);margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px}
[data-bz-node^="s6t4-r"][data-bz-node] p{font-family:Oswald, sans-serif;font-size:22px;font-weight:600;font-style:normal;line-height:normal;letter-spacing:normal;text-transform:none;text-align:start;color:rgb(20, 21, 26);margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px}
[data-bz-node^="s6t4-r"][data-bz-node] a:nth-of-type(1){color:rgb(20, 21, 26);text-decoration:none}
[data-bz-node^="s6t4-r"][data-bz-node] a:nth-of-type(1):hover{color: rgb(196, 18, 48)}
[data-bz-node^="s6b5-r"][data-bz-node] .bz-btn{margin:0;line-height:normal;background:transparent;border:0;border-radius:0;box-shadow:none;padding:0;display:inline-block;color:#C41230;text-decoration:underline;justify-self:start;background:rgb(196, 18, 48);color:rgb(255, 255, 255);text-decoration:none;font-weight:600;font-size:14px;font-family:Oswald, sans-serif;letter-spacing:0.1em;text-transform:uppercase;padding-top:14px;padding-right:24px;padding-bottom:14px;padding-left:24px}
[data-bz-node^="s6b5-r"][data-bz-node] .bz-btn:hover{background: rgb(143, 13, 33)}
[data-bz-node^="s6b5-r"][data-bz-node] .bz-btn:focus{outline: rgb(20, 21, 26) solid 3px; outline-offset: 3px}
[data-bz-node^="s6b5-r"][data-bz-node] .bz-btns{margin:0;gap:0}
[data-bz-node="s6"][data-bz-node]{padding-top:clamp(56px, 8vw, 100px);padding-bottom:clamp(56px, 8vw, 100px)}
